import warnings
warnings.filterwarnings('ignore')

# Test the basic Card functionality
from astropy.io import fits

# Test creating a card and parsing it back
def test_card(value_str, description=''):
    card1 = fits.Card('TEST', value_str)
    card2 = fits.Card.fromstring(str(card1))
    result = card1.value == card2.value
    if not result:
        print(f'FAIL: {description}')
        print(f'  Original: {repr(card1.value)}')
        print(f'  Parsed: {repr(card2.value)}')
    return result

# Run tests
tests_passed = 0
tests_failed = 0

# Test 1: Basic string
if test_card('hello world', 'basic string'):
    tests_passed += 1
else:
    tests_failed += 1

# Test 2: String with single quote
if test_card(\"hello'world\", 'single quote'):
    tests_passed += 1
else:
    tests_failed += 1

# Test 3: String with double single quotes at end
if test_card('x' * 65 + \"''\", 'double single quotes at end'):
    tests_passed += 1
else:
    tests_failed += 1

# Test 4: Empty string
if test_card('', 'empty string'):
    tests_passed += 1
else:
    tests_failed += 1

# Test 5: String starting with quotes
if test_card(\"''hello\", 'starting with quotes'):
    tests_passed += 1
else:
    tests_failed += 1

# Test 6: Long CONTINUE string
if test_card('x' * 100, 'long continue string'):
    tests_passed += 1
else:
    tests_failed += 1

# Test 7: Long string with quotes in middle
if test_card('x' * 50 + \"''\" + 'x' * 50, 'quotes in middle'):
    tests_passed += 1
else:
    tests_failed += 1

# Test 8: Multiple quotes
if test_card(\"x\" * 30 + \"''\" + \"x\" * 30 + \"''\", 'multiple quotes'):
    tests_passed += 1
else:
    tests_failed += 1

# Test 9: All quote combinations at boundary of CONTINUE
for n in [60, 61, 62, 63, 64, 65, 66, 67, 68, 69]:
    if test_card('x' * n + \"''\", f'boundary test n={n}'):
        tests_passed += 1
    else:
        tests_failed += 1

# Test 10: From PR description
for n in range(50, 70):
    val = 'x' * n + \"''\" + 'x' * 10
    if test_card(val, f'PR test n={n}'):
        tests_passed += 1
    else:
        tests_failed += 1

print(f'Tests passed: {tests_passed}')
print(f'Tests failed: {tests_failed}')
"

